            steps {
                git branch: 'main', url: 'https://github.com/your/repo.git'
            }
        }

        stage('Install Dependencies') {
            steps {
                sh 'pip install -r requirements.txt'
            }
        }

        stage('Train Model') {
            steps {
                script {
                    def model_path = "${env.WORKSPACE}/${env.MODEL_PATH}"
                    sh "python train_model.py ${env.DATA_PATH} ${model_path}"
                }
            }
        }

        stage('Evaluate Model') {
            steps {
                script {
                    def model_path = "${env.WORKSPACE}/${env.MODEL_PATH}"
                    sh "python evaluate_model.py ${model_path}"
                }
            }
        }

        stage('Deploy Model') {
            steps {
                script {
