```groovy
def getDynamicWorkerCount() {
    // Example logic to determine the number of workers
    def cpuCores = sh(script: 'nproc', returnStdout: true).trim().toInteger()
    def testCount = sh(script: 'pytest --collect-only | grep -oP "(?<=collected )\\d+(?= items?)"', returnStdout: true).trim().toInteger()
    def systemLoad = sh(script: 'cat /proc/loadavg | awk \'{print $1}\'', returnStdout: true).trim().toDouble()

    def numWorkers = Math.min(cpuCores, Math.ceil(testCount / 100))  // Adjust the divisor as needed
    numWorkers = Math.max(numWorkers, 1)  // Ensure at least one worker
    numWorkers = Math.min(numWorkers, 10)  // Cap the number of workers

    if (systemLoad > 1.5) {
        numWorkers = Math.floor(numWorkers * 0.75)  // Reduce workers if system load is high
    }

    return numWorkers
}
```

