from flask import Flask, request, jsonify
from functools import wraps
import jwt
import auth0

app = Flask(__name__)

# Define Auth0 configuration
AUTH0_CONFIG = {
    'domain': 'mydomain.auth0.com',
    'client_id': 'myclientid',
    'client_secret': 'myclientsecret',
    'api_identifier': 'myapiidentifier'
}

# Initialize Auth0
auth0.init_app(AUTH0_CONFIG)

# Decorator to check JWT token
def requires_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', None)
        if not auth_header:
            return jsonify({"error": "Authorization header is missing"}), 401

        token = auth_header.split()[1]
        try:
            payload = jwt.decode(token, AUTH0_CONFIG['client_secret'], audience=AUTH0_CONFIG['api_identifier'], algorithms=['HS256'])
            if 'https://api/role' in payload and payload['https://api/role'] == 'admin':
                return f(*args, **kwargs)
            else:
                return jsonify({"error": "Unauthorized"}), 403
        except jwt.ExpiredSignatureError:
            return jsonify({"error": "Token expired"}), 401
        except jwt.InvalidTokenError:
            return jsonify({"error": "Invalid token"}), 401
    return decorated

@app.route('/pipeline', methods=['POST'])
@requires_auth
def pipeline_api_call():
    # ... API call code ...
    return jsonify({"message": "Pipeline triggered successfully"}), 200

if __name__ == '__main__':
    app.run(debug=True)
```

