                    docker.build("health-monitoring-service:${BUILD_NUMBER}", "-f Dockerfile.health-monitoring-service .")
                }
            }
        }

        stage('Push Docker Images') {
            steps {
                script {
                    docker.withRegistry('https://registry.hub.docker.com', 'dockerhub-credentials') {
                        docker.image("agent-management-service:${BUILD_NUMBER}").push()
                        docker.image("task-distribution-service:${BUILD_NUMBER}").push()
                        docker.image("metrics-collection-service:${BUILD_NUMBER}").push()
                        docker.image("health-monitoring-service:${BUILD_NUMBER}").push()
