    });
  });
});
```

### Asynchronous API Interactions

Asynchronous interactions involve callbacks, promises, or other mechanisms that handle responses at a later time. Pact can still handle these interactions by defining the expected request and response pairs, even if the response is delayed.

#### Example: Asynchronous POST Request with Callback

```javascript
const { Consumer, Given, Then, UponReceiving } = require('@pact-foundation/pact');

describe('Asynchronous API Interaction', () => {
  const provider = new Consumer({
    consumer: 'AgentClient',
    provider: 'AgentService',
    port: 4000,
  });

  describe('Given an agent needs to be created', () => {
    Given(provider, 'an agent creation request', (req) => ({
      method: 'POST',
      path: '/agents',
      headers: {
        'Content-Type': 'application/json',
      },
      body: {
        name: 'Jane Doe',
        status: 'pending',
      },
    }));

    UponReceiving(provider, 'a request to create an agent', (req) => ({
      status: 201,
      headers: {
        'Content-Type': 'application/json',
      },
      body: {
        id: 2,
        name: 'Jane Doe',
        status: 'created',
      },
    }));

    Then(provider, 'returns the created agent details', (res) => {
      expect(res.status).toBe(201);
      expect(res.body.id).toBe(2);
      expect(res.body.name).toBe('Jane Doe');
      expect(res.body.status).toBe('created');
    });
  });
});
```

### Handling Asynchronous Responses

For asynchronous interactions, you can use Pact's `UponReceiving` to define the expected response and then use `Then` to verify the actual response once it arrives.

#### Example: Asynchronous POST Request with Promise

```javascript
